/* Geoid model: geoid height above the ellipsoid from a grid in flash.
 *
 * The grid (geoid_grid.c) is generated by firmware/tools/geoid_cut.py, cut
 * to an area around the RTK base from Lantmäteriet's SWEN17_RH2000, so
 * h_ell - N is an RH 2000 height. That holds only when the ellipsoid height is
 * in SWEREF 99, that is with RTK from a base given in SWEREF 99; a standalone
 * fix (ITRF) is a few decimetres off. Outside the grid the caller falls back
 * to the receiver's own undulation. Core 0 only; plain host C. */
#ifndef GEOID_H
#define GEOID_H

#include <stdbool.h>
#include <stdint.h>

typedef struct {
    const char    *name;
    double         lat0_deg, lon0_deg;   /* south-west grid point            */
    double         dlat_deg, dlon_deg;   /* grid steps                       */
    int            rows, cols;           /* rows run south to north          */
    float          offset_m;             /* added to every value             */
    const int16_t *mm;                   /* rows * cols, millimetres         */
} geoid_grid_t;

extern const geoid_grid_t geoid_grid;

/* Geoid height N (m) at a point, bilinear between the four nearest grid
 * points. False outside the grid. */
bool geoid_height_m(const geoid_grid_t *g, double lat_deg, double lon_deg, float *n_m);

#endif
